  refs: string[],
  modelRegistry: ExtensionContext['modelRegistry'],
  context: Context,
  currentPhase?: RouterPhase,
  thinking?: ThinkingLevel,
  hasImage?: boolean,
  signal?: AbortSignal,
  stallTimeoutMs?: number,
  onStall?: (ref: string, ms: number) => void,
): Promise<ClassifierResult | undefined> => {
